// The root shim for loose plugin discovery: `<config>/plugins/<name>/index.ts`.
// Package installs resolve `package.json` `exports` "." here too.
//
// The import is dynamic and guarded because a loose copy carries no
// `node_modules`. An unresolvable runtime dependency — `zod`, imported eagerly
// by `src/tools/schema.ts` — then throws during evaluation, and the host blames
// the export instead: "Plugin must export a default definition with an id and an
// effect or setup function". Catching keeps the definition valid and logs the
// package that could not be resolved.
import { fileURLToPath } from "node:url";
import type { Plugin } from "@opencode/plugin/promise/plugin";

let loaded: typeof import("./src/index.ts") | undefined;
let loadError: unknown;
try {
  loaded = await import("./src/index.ts");
} catch (err) {
  loadError = err;
}

if (loadError) {
  // Runs before any hook exists, so the host log is the only surface. The
  // directory names which copy of the plugin failed.
  const where = fileURLToPath(new URL(".", import.meta.url));
  const detail =
    loadError instanceof Error ? loadError.message : String(loadError);
  console.error(
    `opencode-self-improvement: failed to load from ${where}: ${detail}`,
  );
  console.error(
    "opencode-self-improvement: a loose copy under <config>/plugins/ needs its runtime dependencies — run `bun install` in that directory, or install the package with `opencode plugin add opencode-self-improvement`.",
  );
}

// Only used when the import failed. The id is a literal, not `PLUGIN_ID`,
// because it has to be right in exactly the case where that module never
// evaluated — the host keys storage, status and diagnostics on it.
const unloaded: Plugin = {
  id: "opencode-self-improvement",
  async setup() {
    console.error(
      "opencode-self-improvement: loaded with no tools and no hooks — the module failed to evaluate, so nothing is active. Clear the load error above; the store stays empty until it is gone.",
    );
  },
};

export const SelfImprovement: Plugin = loaded?.SelfImprovement ?? unloaded;
export default SelfImprovement;

// opencode-self-improvement: one opencode plugin bundling durable memory, the
// 4-gate write pipeline, deterministic reflection triggers T1/T2/T4,
// tiny-digest injection with deterministic memory-first context and
// contextual pull, and snapshot/rollback.
//
// Registers tools via `ctx.tool.transform` (JSON Schema) and hooks via the
// OpenCode V2 session/tool API. Slash commands are installed as markdown by
// src/command.ts. The default export `{ id, setup(ctx) }` is checked against
// the SDK's Plugin type using a type-only import (see the note on `plugin`).
import { registerHooks } from "./events.ts";
import { forgetUsage } from "./identity/host-events.ts";
import { guarded, setGuardedFailureReporter } from "./core/hooks.ts";
import type { PluginCtx } from "./core/host.ts";
import type { Cleanup, Plugin } from "@opencode/plugin/promise/plugin";
import { basename, join } from "node:path";
import { fileURLToPath } from "node:url";
import { frontierBudget, injectBudget } from "./core/config/budgets.ts";
import { memoryRoot } from "./core/config/paths.ts";
import { loadAll, malformedCount } from "./store/files/load.ts";
import { snapshotFiles } from "./store/files/snapshots.ts";
import {
  clearSuperseded,
  markManySuperseded,
  markSuperseded,
} from "./store/files/supersede.ts";
import { resolveMemoryTarget } from "./store/files/target.ts";
import { type Memory } from "./store/model/memory.ts";
import { isActive, isInjectable } from "./store/model/predicates.ts";
import { evidenceVisibleTo, isVisibleTo } from "./store/model/visibility.ts";
import { auditCaveat, sameStrList, type WriteCandidate } from "./gate/gate.ts";
import { withStoreLock } from "./store/lock.ts";
import {
  isQuarantined,
  quarantineReasons,
} from "./store/quarantine/quarantine.ts";
import { pruneMemory } from "./store/prune.ts";
import { findStaleOpen } from "./portable/decay.ts";
import { exportMemories } from "./portable/export.ts";
import { importMemories } from "./portable/import.ts";
import { listSnapshots, restoreSnapshot } from "./store/undo.ts";
import { evidenceFileFor, record } from "./telemetry/record.ts";
import { proposeConsolidations } from "./consolidate/propose.ts";
import { renderProposals } from "./consolidate/render.ts";
import { readReads } from "./telemetry/ledger.ts";
import { formatMemory } from "./inject/format.ts";
import { sharedTerms } from "./recall/shared-terms.ts";
import {
  configureAutoCapture,
  CAPTURE_EVENT_TYPES,
} from "./capture/runtime.ts";
export {
  resetCaptureCooldowns,
  TURN_END_EVENTS,
  CAPTURE_EVENT_TYPES,
  captureTriggerFor,
} from "./capture/runtime.ts";
export { resetSessionModels } from "./capture/session-model.ts";
import { createInjectionEpochs } from "./inject/epochs.ts";
import { pullScopeFrom } from "./inject/pull.ts";
import { createSessionContext } from "./identity/session-context.ts";
import { registerMemoryTools } from "./tools/registry.ts";
import {
  readLedger,
  neverRetrieved,
  recordHits,
  type HitSource,
} from "./telemetry/ledger.ts";
import { formatInit } from "./init/format.ts";
import { runInit } from "./init/run.ts";
import { ensureInitCommand, ensureMemoryReportCommand } from "./init/ensure.ts";
import { captureLag, captureLagLines, rowsPerDay } from "./status/metrics.ts";
import { type Measured, type StoreCounts } from "./status/payload.ts";
import { renderMemoryReport } from "./status/report.ts";
import { blockedRecent } from "./status/write.ts";
import { firstFrontierTap, markFrontierTap } from "./capture/triggers.ts";
import { peekTurn, setCurrent } from "./core/state.ts";
import {
  resolveRepo,
  setRepoScope,
  rememberSessionDir,
  bindSessionProvisional,
  writeTarget,
} from "./identity/repokey.ts";
import { parseLine } from "./core/logfmt/format.ts";
import { readLines } from "./core/logfmt/read.ts";
import { parseModelRef } from "./capture/candidates.ts";
import { flattenMemoryText } from "./store/sanitize.ts";
import { bunFloorWarning } from "./core/runtime.ts";

// Tool/input boundaries are zod schemas (src/schema.ts): the JSON Schema the
// host sees is GENERATED from them, and raw args are re-parsed at execution.
import {
  DecayArgs,
  EmptyArgs,
  EvidenceArgs,
  ExportArgs,
  ForgetArgs,
  ImportArgs,
  InitArgs,
  ConsolidateArgs,
  MergeReviewArgs,
  RecallArgs,
  RememberArgs,
  UndoArgs,
  UpdateArgs,
  validated,
} from "./tools/schema.ts";

const PLUGIN_ID = "opencode-self-improvement";

// The setup-time Bun-floor warning fires once per process (setup can run for
// more than one location).
let bunFloorChecked = false;

// The real setup implementation, written against the loose local PluginCtx
// (the only members of the V2 context this plugin actually touches).
const impl = {
  async setup(ctx: PluginCtx): Promise<Cleanup | void> {
    // Identity vs verification tree are separate concerns: the repo STAMP is
    // resolved per session from the event stream (never from process.cwd(),
    // which is the server launch dir and poisons rows invisibly); cwd remains
    // only as the gate's verification tree when no session location is known.
    const setupRoot = ctx?.location?.directory;
    const liveRoot = setupRoot ?? process.cwd();
    // mirror every swallowed guarded() failure into the evidence file.
    // Hook name + error class ONLY — never the message, which can carry
    // conversation content. Fire-and-forget: evidence must not add a failure
    // to a path that already failed softly.
    setGuardedFailureReporter((name, err) =>
      record(
        "hook_error",
        {
          hook: name,
          error:
            err instanceof Error
              ? err.constructor?.name || "Error"
              : typeof err,
        },
        false,
      ).catch(() => {}),
    );
    setRepoScope(setupRoot ? resolveRepo(setupRoot) : null);
    // THIS instance's own workspace. The module scope says who loaded last;
    // this says who I am. An unbound session that calls into THIS instance
    // resolves here — never to another instance's scope (multi-setup).
    const instanceDir =
      typeof setupRoot === "string" && setupRoot ? setupRoot : undefined;

    // Character budgets: relevance injection and contextual pulls share the
    // existing cap; the session-start frontier has its own larger cap. Plugin
    // options win over env fallbacks, and the frontier defaults to 3x the
    // effective injection budget.
    const budget = Number(ctx.options?.injectBudget) || injectBudget();
    const openBudget =
      Number(ctx.options?.frontierBudget) || frontierBudget(budget);

    // Warn-once Bun floor check (same setup-time warning style as the
    // captureModel warnings below): opencode embeds Bun, and the store code's
    // fs failure modes are Bun-version dependent, so flag an old host.
    if (!bunFloorChecked) {
      bunFloorChecked = true;
      const floorWarning = bunFloorWarning(
        typeof Bun === "undefined" ? undefined : Bun.version,
      );
      if (floorWarning) console.warn(floorWarning);
    }

    // Mirror the /repo-init slash command into opencode's global commands dir
    // (idempotent, write-if-missing). OpenCode 2.x loads `*.md` from
    // ~/.config/opencode/commands, so this is the canonical V2 install path.
    await ensureInitCommand();
    await ensureMemoryReportCommand();

    const {
      gateContext,
      ownerlessWriter,
      refuseOwnerlessWrite,
      toolIds,
      bindSessionFromApi,
      bindSessionIdentity,
    } = createSessionContext(ctx, { instanceDir, liveRoot });

    // ---- tools --------------------------------------------------------------
    // Use ledger. `query` is what retrieval was asked with; what gets
    // stored is the vocabulary the answer SHARES with the query, taken from the
    // memory side, so the ledger can never become a copy of user prompts.
    // Fail-soft inside recordHits: telemetry must not break a read path.
    const noteHits = async (
      src: HitSource,
      sid: string,
      rows: Memory[],
      query: string,
    ): Promise<void> => {
      if (!rows.length || !query.trim()) return;
      const terms: string[] = [];
      for (const m of rows)
        for (const t of sharedTerms(query, m))
          if (!terms.includes(t)) terms.push(t);
      // the turn is what joins a ride to the outcome of that same turn.
      // Read, never created-for: markTurn has already run for any session that
      // can reach a read path, so this does not seed state.
      const observed = peekTurn(sid);
      await recordHits(
        src,
        sid,
        rows,
        terms,
        Date.now(),
        observed?.turn,
        observed?.key,
      );
    };
    // The host listener owns measured usage; the epoch controller drops it
    // alongside its own maps when the shared session LRU evicts an entry.
    const measuredTurns = new Map<string, Measured>();
    const sessions = createInjectionEpochs({
      budget,
      frontierBudget: openBudget,
      // Code-check guided claims by default; explicit false opts out.
      contradictionSurface: ctx.options?.contradictionSurface !== false,
      measuredTurns,
      forgetUsage,
      noteHits: (sid, rows, query) => noteHits("inject", sid, rows, query),
    });
    const flushStatus = sessions.flushStatus;

    await ctx.tool?.transform((editor) =>
      registerMemoryTools(editor, {
        toolIds,
        bindSessionIdentity,
        ownerlessWriter,
        refuseOwnerlessWrite,
        gateContext,
        sessions,
        noteHits,
        direct: { codemode: false } as const,
      }),
    );
    // ---- hooks (all fail-closed) -------------------------------------------
    // Seam set by the auto-capture wiring below ONLY when the compaction
    // trigger is live (autoCapture not false, captureOnCompact not false, and a
    // model that resolves — the option, the session, or the host default). The
    // compaction hook calls it fire-and-forget; undefined means "off".
    // Declared here because the hook registers before capture.
    let onCompactCapture:
      | ((sid: string, messages: unknown) => void)
      | undefined;

    const measuredController = await registerHooks(ctx, {
      guarded,
      sessions,
      instanceDir,
      budget,
      noteHits,
      bindSessionIdentity,
      bindSessionFromApi,
      measuredTurns,
      flushStatus,
      // Which tool results carry a pull, and what the pull searches. Measured
      // default in src/inject/pull.ts; `pullOutputChars: 0` in the plugin config
      // restores the old arguments-only behaviour, `pullTools` narrows the set,
      // and `pullTools: []` switches the channel off. A value that does not
      // parse falls back to the measured default and says so on the console —
      // the same setup-time warning style as the Bun floor and captureModel
      // checks above, because a config line that silently does nothing is the
      // failure nobody debugs.
      pullScope: pullScopeFrom(ctx.options, (message) =>
        console.warn(`[opencode-self-improvement] ${message}`),
      ),
      getCompactCapture: () => onCompactCapture,
    });
    // ---- auto-capture (turn-end + compaction triggers) ---------------------
    // Armed unless the config sets `autoCapture: false`. (The measured-cache
    // listener above also subscribes to the event stream, and it is
    // zero-model: pure bookkeeping of message usage.) While armed — the switch
    // not false, and a parseable `captureModel` whenever one is given — each
    // supported turn-end event, and unless `captureOnCompact` is false each
    // compaction hook call too, runs ONE cheap ctx.generate.text call whose
    // reply is parsed into candidates that go through the SAME runWriteGate as
    // model-authored writes — capture can never bypass the moat, and it only
    // ever writes through the gate. A per-session, per-trigger cooldown bounds
    // the cost. Compaction-triggered rows carry the CAPTURE_COMPACT_TAG tag and
    // auto_capture_compaction_* evidence lines, idle rows keep auto_capture_*,
    // so decay/status — and bench/runners/capture-trigger-compare.ts — can measure
    // which trigger earns its tokens. Every failure is swallowed: capture must
    // never be able to break a session.
    const capture = configureAutoCapture(ctx, {
      instanceDir,
      gateContext,
      guarded,
      // Fix A (FINDINGS 2026-11-08 §4b): guided promotion moves every tracked
      // epoch, so a late guided row enters the hint lane on each session's
      // next request instead of waiting for a request that happens to notice.
      onGuidedPromoted: async () => {
        await sessions.refreshAll();
      },
    });
    onCompactCapture = capture.onCompactCapture;
    const captureCleanup = capture.cleanup;
    // ---- startup heartbeat ------------------------------------------
    // Every other evidence line is written BY something that already worked,
    // so "capture is off", "capture is misconfigured" and "capture is armed and
    // inert" were indistinguishable from anything a user could read - which is
    // exactly how a pipeline that had never run in ten days survived a review
    // and a merge. This one line makes the ABSENCE of capture activity
    // interpretable: `capture=` names why, `subscribed=` lists the event types
    // the subscription actually reacts to. Guarded like every other hook: a
    // broken store must not turn plugin load into a throw.
    await guarded("plugin_load heartbeat", async () => {
      let pluginVersion = "unknown";
      // Which COPY of this plugin the host actually loaded. Version alone could
      // not answer it: a checkout and the published package it came from share
      // a version, and the npm cache has held a stale one while a session ran
      // against something else entirely. The heartbeat now names the directory,
      // so "is my change live?" is one grep instead of an afternoon.
      let entryDir = "unknown";
      try {
        const pkg = await Bun.file(
          new URL("../package.json", import.meta.url),
        ).json();
        if (typeof pkg?.version === "string") pluginVersion = pkg.version;
      } catch {
        // a heartbeat with an unknown version still beats no heartbeat
      }
      try {
        entryDir = fileURLToPath(new URL("../", import.meta.url));
      } catch {
        // same: the version line is still worth emitting
      }
      // Auto-capture is armed unless the config opts it out: an absent key
      // means on, so the switch is read as a negative opt-out.
      const wantCapture = ctx.options?.autoCapture !== false;
      // an omitted captureModel is a valid arm — the capture inherits
      // the session's model (session.context) or the host default. Only an
      // explicit but malformed string is invalid_model.
      const captureModelOpt = ctx.options?.captureModel;
      const modelOk =
        captureModelOpt === undefined || !!parseModelRef(captureModelOpt);
      const capabilities = [
        "event.subscribe",
        "generate.text",
        "session.context",
      ].filter((name) => {
        const [domain, method] = name.split(".");
        return (
          typeof (ctx as unknown as Record<string, any>)?.[domain]?.[method] ===
          "function"
        );
      });
      const captureState = !wantCapture
        ? // captureOnCompact alone is a distinct misconfiguration (the
          // runtime warns about it and stays disabled) — name it, or "off
          // (default)" and "wrong switch set" share one line.
          ctx.options?.captureOnCompact === true
          ? "switch_mismatch"
          : "off"
        : !modelOk
          ? "invalid_model"
          : capabilities.length < 3
            ? "no_capabilities"
            : "on";
      await record(
        "plugin_load",
        {
          version: pluginVersion,
          entry: entryDir,
          capture: captureState,
          capture_on_compact: ctx.options?.captureOnCompact !== false,
          capabilities: `[${capabilities.join(",")}]`,
          subscribed: `[${CAPTURE_EVENT_TYPES.join(",")}]`,
          inject_budget: injectBudget(),
          store_rows: (await loadAll()).length,
        },
        false,
      );
    });
    // Single cleanup returned by setup: tears down the measured listener and,
    // when enabled, the capture subscription. Future teardowns merge in here.
    return () => {
      measuredController.abort();
      if (captureCleanup) return captureCleanup();
    };
  },
};

// The plain object IS the V2 contract ({ id, setup }); the SDK's `Plugin` type
// pins its shape at compile time. The import is deliberately type-only:
// opencode installs npm plugins with runtime dependencies only, so a value
// import of @opencode/plugin —
// a devDependency here — would fail to resolve at load time for published
// consumers, and making it a runtime dependency would pull effect +
// @opencode/client into every install, the exact dead-weight problem dropping
// the V1 SDK fixes. `Plugin.define` is an identity function at runtime, so this
// annotation buys the same compile-time contract for zero runtime cost.
const plugin: Plugin = {
  id: PLUGIN_ID,
  setup: async (ctx) => impl.setup(ctx as unknown as PluginCtx),
};

export const SelfImprovement = plugin;
export default plugin;

// Memory Viewer server. Bundled with the plugin: run `bun memory-view` (or
// `bun run src/viewer/server.ts`) from the repo root and open the printed URL.
// Defaults to 127.0.0.1 — the memory store is local, personal data. All reads go
// through the same loadAll() used by recall/inject (so blocked entries are
// hidden), and all mutations are non-destructive (snapshot + audit + supersede).
// I2: serves only file data; never writes into any repo.
// A non-loopback bind or allowed host mints a startup token (0600, in
// the store root) and every request must present it; loopback stays open.
import { basename, join } from "node:path";
import { linkSync, readFileSync, renameSync, rmSync } from "node:fs";
import { isIP } from "node:net";
import { randomBytes, timingSafeEqual } from "node:crypto";
import { serve, type Server } from "bun";
import { z, type ZodTypeAny } from "zod";
import {
  BlockBody,
  DeleteBody,
  EditBody,
  RestoreEntryBody,
  UnblockBody,
  UnrejectBody,
  ReleaseQuarantineBody,
} from "../tools/schema.ts";
import {
  deletionsFile,
  memoryRoot,
  snapshotDir,
} from "../core/config/paths.ts";
import { blockedEntries } from "../store/blocklist.ts";
import { LOCK_WRITE, withStoreLock } from "../store/lock.ts";
import { listSnapshots, restoreSnapshot } from "../store/undo.ts";
import { appendMemory } from "../store/files/append.ts";
import { loadAll, memoryFiles } from "../store/files/load.ts";
import { type MemoryStatus } from "../store/model/memory.ts";
import { parseLine } from "../core/logfmt/format.ts";
import { readLines } from "../core/logfmt/read.ts";
import { releaseQuarantinedMemory } from "./mutate.ts";
import {
  isQuarantined,
  quarantineReasons,
} from "../store/quarantine/quarantine.ts";
import {
  deleteMemory,
  editMemory,
  blockMemory,
  unblockMemory,
  unrejectMemory,
  type MutationResult,
} from "./mutate.ts";
import { tombstones } from "../store/tombstones/tombstone.ts";
import { assertViewerWriteAllowed } from "./rejections.ts";
import { preparePrivateFile } from "../core/permissions.ts";

const PAGE = join(import.meta.dir, "page.html");
const HOST = process.env.OPENCODE_VIEWER_HOST || "127.0.0.1";
const PORT = Number(process.env.OPENCODE_VIEWER_PORT || 8787);

// Defense-in-depth headers on every response. CSP: the page uses only inline
// script/style and same-origin fetch, so everything else is off — a stored-XSS
// payload gains no exfil channel and no framing.
const SECURITY_HEADERS: Record<string, string> = {
  "x-content-type-options": "nosniff",
  "content-security-policy":
    "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; " +
    "connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...SECURITY_HEADERS, "content-type": "application/json" },
  });
}

function error(msg: string, status = 400): Response {
  return json({ error: msg }, status);
}

// Binding 127.0.0.1 keeps other machines out, but not other websites open in
// the user's browser. Two checks close that:
// - Host must name this viewer. A DNS-rebinding page reaches 127.0.0.1 under
//   its own hostname, so its requests arrive with a foreign Host.
// - Writes must be JSON from this viewer's own origin. A cross-site form or
//   no-cors fetch can POST text/plain without a CORS preflight, and every
//   memory edited here is injected into the agent's system prompt.
// A viewer deliberately exposed under another name (OPENCODE_VIEWER_HOST set
// to a LAN address, a hostname) can list it in OPENCODE_VIEWER_ALLOWED_HOSTS.
function allowedHostnames(): Set<string> {
  const extra = (process.env.OPENCODE_VIEWER_ALLOWED_HOSTS ?? "").split(",");
  const names = ["127.0.0.1", "localhost", "::1", HOST, ...extra]
    .map((n) => n.trim().toLowerCase())
    .filter(Boolean)
    .map((n) => (n.includes(":") && !n.startsWith("[") ? `[${n}]` : n));
  return new Set(names);
}

function isLoopbackHostname(name: string): boolean {
  // allowedHostnames supplies trimmed, lower-cased names (IPv6 bracketed).
  const host = name.replace(/^\[|\]$/g, "");
  if (host === "localhost") return true;
  if (isIP(host) === 4) return host.startsWith("127.");
  // Closed spellings only: URL parsing throws on IPv6 zone ids. Ambiguous
  // aliases (including abbreviated IPv4) conservatively trigger the warning.
  return host === "::1" || host === "0:0:0:0:0:0:0:1";
}

// A non-loopback bind or allowed host must not expose the store as open HTTP:
// a token is minted at startup and every request must present it. The
// Host/Origin layer stays as the CSRF defence it always was, but it is not
// the only thing between the LAN and the store.
const TOKEN_FILE = "viewer.token";
const TOKEN_COOKIE = "osi-viewer";
const TOKEN_SHAPE = /^[0-9a-f]{64}$/;

function tokenPath(): string {
  return join(memoryRoot(), TOKEN_FILE);
}

// Reuse a token already in the file so a restart does not invalidate URLs a
// human has open (and two viewers sharing a store share one token); mint a
// fresh one otherwise. Concurrent first starts — same process or separate
// processes — must agree on ONE token: the claim is an atomic hard-link of a
// fully-written 0600 temp, so exactly one starter's content lands at the path
// (link(2) refuses an existing target), and every loser reads back the
// winner's complete token instead of overwriting the file with its own.
//
// The hard-link claim solves an ABSENT file, not a CORRUPT one. Replacing a
// corrupt file unconditionally makes concurrent starters disagree on Linux and
// throw EPERM on Windows, so recovery is serialized twice over: within one
// process every mint runs through this promise chain, so the second starter
// re-reads the repaired file instead of racing the repair; across processes an
// O_EXCL lock file elects one repairman and the others adopt its token. A
// replacement is never unconditional.
//
// The reuse path enforces the 0600 contract too. preparePrivateFile tightens
// an existing file to owner-only (keeping owner bits, refusing a
// final-component symlink), so a token file left world-readable is repaired
// before it is accepted.
//
// History: docs/adr/0004.
let mintTail: Promise<unknown> = Promise.resolve();

function mintViewerToken(): Promise<string> {
  const run = mintTail.then(() => mintTokenOnce());
  mintTail = run.catch(() => {});
  return run;
}

function readToken(path: string): string {
  try {
    return readFileSync(path, "utf8").trim();
  } catch {
    return "";
  }
}

async function mintTokenOnce(): Promise<string> {
  const path = tokenPath();
  const prior = readToken(path);
  if (TOKEN_SHAPE.test(prior)) {
    preparePrivateFile(path);
    return prior;
  }
  const token = randomBytes(32).toString("hex");
  const tmp = `${path}.${process.pid}.${randomBytes(4).toString("hex")}.tmp`;
  try {
    preparePrivateFile(tmp);
    await Bun.write(tmp, token);
    try {
      linkSync(tmp, path);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "EEXIST") throw err;
      const winner = readToken(path);
      if (TOKEN_SHAPE.test(winner)) return winner;
      return await recoverCorruptToken(path, tmp, token);
    }
    return token;
  } finally {
    rmSync(tmp, { force: true });
  }
}

// Repair a corrupt token file: exactly one starter replaces the file and the
// rest adopt its token. The repair also keeps Windows from renaming onto a
// file a rival starter is mid-read — the EPERM that motivated it.
//
// It takes the STORE's lock. Lock state must not live in a directory entry:
// on Windows an O_EXCL marker outlives the holder whenever a third-party
// handle is open without FILE_SHARE_DELETE, and an age-based steal cannot
// rescue that case because the steal is itself an unlink subject to the same
// refusal — a viewer that hit it could never start again.
//
// History: docs/adr/0004.
async function recoverCorruptToken(
  path: string,
  tmp: string,
  token: string,
): Promise<string> {
  return withStoreLock(
    path,
    async () => {
      // Re-read inside the lock: a rival repair may have completed while this
      // call waited, and its token is the one URLs in this store already carry.
      const settled = readToken(path);
      if (TOKEN_SHAPE.test(settled)) return settled;
      renameSync(tmp, path);
      return token;
    },
    LOCK_WRITE,
  );
}

function tokenMatches(candidate: string, expected: string): boolean {
  const a = Buffer.from(candidate);
  const b = Buffer.from(expected);
  return a.length === b.length && timingSafeEqual(a, b);
}

// No decodeURIComponent: the cookie is a fixed-hex token we mint and set
// verbatim, and decoding junk like `osi-viewer=%` throws URIError on the
// auth path — a 500 where a malformed credential must simply be refused.
// The raw value cannot match, so it falls through to 401.
function cookieValue(req: Request, name: string): string | null {
  for (const part of (req.headers.get("cookie") ?? "").split(";")) {
    const eq = part.indexOf("=");
    if (eq !== -1 && part.slice(0, eq).trim() === name)
      return part.slice(eq + 1).trim();
  }
  return null;
}

function exposureWarning(path: string): string {
  return (
    "[memory-viewer] WARNING: non-loopback hosts are allowed. Every request " +
    "must present the startup-minted token (Authorization: Bearer, the " +
    TOKEN_COOKIE +
    " cookie, or ?token= on /); requests without it are refused with 401. " +
    "Token: " +
    path +
    " (mode 0600). Plain HTTP still exposes the token on the wire — use " +
    "only on a network you trust."
  );
}

function rejectRequest(req: Request, url: URL, port: number): Response | null {
  if (
    !allowedHostnames().has(url.hostname) ||
    (url.port || "80") !== String(port)
  ) {
    return error("unexpected Host header", 403);
  }
  if (req.method === "GET" || req.method === "HEAD") return null;
  const origin = req.headers.get("origin");
  if (origin !== null && origin !== url.origin)
    return error("cross-origin request refused", 403);
  const type = (req.headers.get("content-type") ?? "")
    .split(";")[0]
    .trim()
    .toLowerCase();
  if (type !== "application/json")
    return error("content-type must be application/json", 415);
  return null;
}

interface Row {
  ts: string;
  type: string;
  scope: string;
  content: string;
  reason?: string;
  // Origin stamp: what the row carried when it was deleted, so the
  // restore-entry round trip can restore the row's ORIGINAL visibility.
  repo?: string;
  repoPath?: string;
  // the deleted row's metadata, read back from the audit line, so the
  // deleted-entry UI can show WHAT is being restored — in particular whether
  // it is quarantined. Only deletion rows carry these; blocked rows do not.
  tags?: string[];
  kw?: string[];
  issue?: string;
  status?: string;
  quarantined?: boolean;
}

// Comma-joined scalars back into arrays, the inverse of the audit write.
function splitScalar(value: unknown): string[] | undefined {
  return typeof value === "string" && value
    ? value.split(",").filter(Boolean)
    : undefined;
}

// The metadata a deletion audit line carries for the deleted row.
// Kept out of the client contract: restore resolves it here, from the store's
// own record, rather than trusting replayed bytes.
interface DeletionMeta {
  tags?: string[];
  kw?: string[];
  issue?: string;
  status?: MemoryStatus;
  repo?: string;
  repoPath?: string;
}

function auditMeta(f: NonNullable<ReturnType<typeof parseLine>>): DeletionMeta {
  const tags = splitScalar(f.tags);
  const kw = splitScalar(f.kw);
  return {
    ...(tags ? { tags } : {}),
    ...(kw ? { kw } : {}),
    ...(typeof f.issue === "string" && f.issue ? { issue: f.issue } : {}),
    ...(f.status === "open" || f.status === "settled"
      ? { status: f.status }
      : {}),
    ...(typeof f.repo === "string" && f.repo ? { repo: f.repo } : {}),
    ...(typeof f.repoPath === "string" && f.repoPath
      ? { repoPath: f.repoPath }
      : {}),
  };
}

// Deleted entries live only in the audit log (their memory line was removed),
// so surface the recorded data + reason from deletions.logfmt.
async function deletedRows(): Promise<Row[]> {
  const lines = await readLines(deletionsFile());
  return lines
    .map((l) => parseLine(l))
    .filter((f): f is NonNullable<typeof f> => f !== null)
    .map((f) => {
      const meta = auditMeta(f);
      return {
        ts: String(f.original_ts ?? f.ts ?? ""),
        type: String(f.type ?? ""),
        scope: String(f.scope ?? ""),
        content: String(f.content ?? ""),
        reason: String(f.reason ?? ""),
        ...meta,
        // the operator must SEE that a deleted row was quarantined —
        // restoring it must not read as a way to release quarantine.
        ...(meta.tags
          ? { quarantined: isQuarantined({ tags: meta.tags }) }
          : {}),
      };
    });
}

// The authoritative record of what a deleted row carried, keyed by the deleted
// row's ts. The LAST matching line wins: a row edited then deleted has
// its newest state last, and that is the state a restore re-adds. Audit lines
// written before deletion metadata existed carry none — the documented fallback.
async function deletionAuditFor(ts: string): Promise<DeletionMeta | undefined> {
  let found: DeletionMeta | undefined;
  for (const line of await readLines(deletionsFile())) {
    const f = parseLine(line);
    if (!f || f.original_ts !== ts) continue;
    found = auditMeta(f);
  }
  return found;
}

// Same record, keyed by the deleted row's identity instead of its ts.
// A restore request that omits ts is a legacy REQUEST, not a legacy record:
// if the audit carries a matching line, that line is still the authoritative
// copy of what the row carried, and resolving it here closes the laundering
// path (omitting ts must not restore a known quarantined row as injectable).
// Only when NO line matches — a client older than the viewer, or a row whose
// deletion predates the audit — does the route fall back to client replay.
async function deletionAuditByRow(
  type: string,
  scope: string,
  content: string,
): Promise<DeletionMeta | undefined> {
  let found: DeletionMeta | undefined;
  for (const line of await readLines(deletionsFile())) {
    const f = parseLine(line);
    if (!f || f.type !== type || f.scope !== scope || f.content !== content)
      continue;
    found = auditMeta(f);
  }
  return found;
}

// Blocked entries are still on disk but hidden by the blocklist; scan every
// memory file and keep the ones whose ts is blocked, with their full data.
async function blockedRows(): Promise<Row[]> {
  const blocked = await blockedEntries();
  const byTs = new Map(blocked.map((b) => [b.ts, b.reason]));
  const out: Row[] = [];
  for (const file of await memoryFiles()) {
    for (const line of await readLines(file)) {
      const f = parseLine(line);
      if (!f || typeof f.ts !== "string") continue;
      if (!byTs.has(f.ts)) continue;
      out.push({
        ts: f.ts,
        type: String(f.type ?? ""),
        scope: String(f.scope ?? ""),
        content: String(f.content ?? ""),
        reason: byTs.get(f.ts) ?? "",
      });
    }
  }
  return out;
}

export interface ViewerServer {
  // No websocket routes, so the WebSocketData generic is undefined — the
  // default Bun.serve infers here. Was `any`, which hid the real shape.
  server: Server<undefined>;
  url: string;
  /** The minted token when exposure requires auth; null on a loopback-only bind. */
  token: string | null;
}

export async function startViewer(port: number = PORT): Promise<ViewerServer> {
  const page = await Bun.file(PAGE).text();
  // The same condition that used to only warn now switches authentication on:
  // if any allowed name can be reached from another machine, the token is
  // mandatory for every request, reads included (the store is the blast
  // radius of a read too). Loopback-only binds keep the token-free flow.
  const exposed = [...allowedHostnames()].some(
    (host) => !isLoopbackHostname(host),
  );
  const viewerToken = exposed ? await mintViewerToken() : null;
  const server = serve({
    hostname: HOST,
    port,
    // Without this, an uncaught throw gets Bun's development error page, which
    // includes the stack trace and local file paths. The stack still goes to
    // the terminal.
    error: (e) => {
      console.error(e);
      return error("internal error", 500);
    },
    fetch(req, srv) {
      // Bun builds req.url from the request's Host header. A malformed Host
      // (`127.0.0.1.8787`, an out-of-range port, `exa mple`) makes it
      // unparseable, and the URL parse THROWs — before rejectRequest could
      // answer. Letting that escape hands the caller Bun's dev error page
      // (stack + absolute paths), so the parse itself is the first guarded
      // step.
      let url: URL;
      try {
        url = new URL(req.url);
      } catch {
        return error("malformed request URL (bad Host header?)", 400);
      }
      const rejected = rejectRequest(req, url, server.port ?? port);
      if (rejected) return rejected;
      if (viewerToken !== null) {
        // Bearer header or cookie on every path; the raw ?token= is accepted
        // on / only, as the bootstrap a human pastes once. The page's own
        // fetches are same-origin and carry the cookie, so the token never
        // has to appear in an API URL (or in a log line).
        const auth = req.headers.get("authorization");
        const bearer =
          auth && /^Bearer /i.test(auth) ? auth.slice(7).trim() : null;
        const cookie = cookieValue(req, TOKEN_COOKIE);
        const bootstrap =
          url.pathname === "/" ? url.searchParams.get("token") : null;
        // Validate every presentation instead of taking the first PRESENT
        // one (F2): a stale cookie from before a supported
        // token regeneration must not shadow the freshly printed bootstrap
        // URL. A request with no valid credential is still refused.
        const accepted =
          (bearer !== null && tokenMatches(bearer, viewerToken)) ||
          (cookie !== null && tokenMatches(cookie, viewerToken)) ||
          (bootstrap !== null && tokenMatches(bootstrap, viewerToken));
        if (!accepted) return error("viewer authentication required", 401);
      }
      if (url.pathname === "/") {
        const headers: Record<string, string> = {
          ...SECURITY_HEADERS,
          "content-type": "text/html; charset=utf-8",
        };
        if (viewerToken !== null)
          headers["set-cookie"] =
            `${TOKEN_COOKIE}=${viewerToken}; HttpOnly; SameSite=Strict; Path=/`;
        return new Response(page, { headers });
      }
      if (req.method === "GET" && url.pathname === "/api/data") {
        return loaded().then(
          (d) => json(d),
          () => error("failed to load memory data"),
        );
      }
      return route(req, url).catch((e) =>
        error(e instanceof Error ? e.message : String(e)),
      );
    },
  });
  const bound = server.port ?? port;
  // Warn after binding; wildcard binds (0.0.0.0 and ::) are non-loopback too.
  if (exposed) console.warn(exposureWarning(tokenPath()));
  return {
    server,
    url: viewerToken
      ? `http://${HOST}:${bound}/?token=${viewerToken}`
      : `http://${HOST}:${bound}/`,
    token: viewerToken,
  };
}

async function loaded(): Promise<Record<string, unknown>> {
  const [memories, blocked, deleted, snaps, rejections] = await Promise.all([
    loadAll(),
    blockedRows(),
    deletedRows(),
    listSnapshots(),
    tombstones(),
  ]);
  const blockedByTs = new Set(blocked.map((b) => b.ts));
  return {
    roots: { memoryRoot: memoryRoot(), snapshotDir: snapshotDir() },
    memories: memories.map((m) => ({
      ts: m.ts,
      type: m.type,
      scope: m.scope,
      content: m.content,
      issue: m.issue,
      tags: m.tags,
      quarantined: isQuarantined(m),
      quarantinePatterns: quarantineReasons(m),
      superseded_by: m.superseded_by,
      reason: m.reason,
      // The viewer is the explicit ADMIN read surface (header comment): it
      // lists every repository, and now says WHICH one each row belongs to.
      repo: m.repo,
      repoPath: m.repoPath,
      blocked: blockedByTs.has(m.ts),
    })),
    blocked,
    deleted,
    // the value-keyed rejections. Hashes and metadata only — the store
    // never held the prose, so there is nothing to reveal here either. The
    // sketch is omitted: it is matching machinery, not something a reader can
    // act on.
    rejections: rejections.map((t) => ({
      ch: t.ch,
      reason: t.reason,
      source: t.source,
      scope: t.scope ?? "",
      type: t.type ?? "",
      rejected_at: t.rejected_at,
    })),
    snapshots: snaps.map((s) => ({ name: s.name, bytes: s.bytes })),
  };
}

async function route(req: Request, url: URL): Promise<Response> {
  if (req.method === "POST") {
    const body: unknown = await req.json().catch(() => ({}));
    if (url.pathname === "/api/edit")
      return parseWith(EditBody, body, editRoute);
    if (url.pathname === "/api/delete")
      return parseWith(DeleteBody, body, deleteRoute);
    if (url.pathname === "/api/block")
      return parseWith(BlockBody, body, blockRoute);
    if (url.pathname === "/api/unblock")
      return parseWith(UnblockBody, body, unblockRoute);
    if (url.pathname === "/api/release-quarantine") {
      return parseWith(ReleaseQuarantineBody, body, async ({ ts, reason }) =>
        json(await releaseQuarantinedMemory(ts, reason)),
      );
    }
    if (url.pathname === "/api/unreject")
      return parseWith(UnrejectBody, body, unrejectRoute);
    if (url.pathname === "/api/restore-entry")
      return parseWith(RestoreEntryBody, body, restoreEntryRoute);
    // /api/restore is deliberately NOT schema-parsed here: its name check is
    // basename + pinned-grammar CONTAINMENT, not a shape gate,
    // and its regression tests pin that behavior.
    if (url.pathname === "/api/restore")
      return restoreRoute(body as Record<string, unknown>);
  }
  return json({ error: "not found" }, 404);
}

// Boundary shape check for POST routes: the old `String(body.ts ?? "")`
// coercion made ANY junk
// fit — ts:{} became "[object Object]" as a row identity, a missing content
// appended an empty row. A malformed call now gets a clean 400; semantics
// (which row, what for) stay with the mutate layer.
function parseWith<S extends ZodTypeAny>(
  schema: S,
  body: unknown,
  h: (data: z.infer<S>) => Response | Promise<Response>,
): Response | Promise<Response> {
  const p = schema.safeParse(body);
  if (!p.success) {
    return error(
      `invalid request: ${p.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("; ")}`,
      400,
    );
  }
  return h(p.data);
}

async function editRoute(body: z.infer<typeof EditBody>): Promise<Response> {
  const r: MutationResult = await editMemory({
    ts: body.ts,
    type: body.type,
    scope: body.scope,
    content: body.content,
    issue: body.issue,
    tags: body.tags,
    reason: body.reason,
  });
  return json(r);
}

async function deleteRoute(
  body: z.infer<typeof DeleteBody>,
): Promise<Response> {
  return json(await deleteMemory({ ts: body.ts, reason: body.reason }));
}

async function blockRoute(body: z.infer<typeof BlockBody>): Promise<Response> {
  return json({ ts: await blockMemory(body) });
}

async function unblockRoute(
  body: z.infer<typeof UnblockBody>,
): Promise<Response> {
  return json({ unblocked: await unblockMemory(body.ts) });
}

// The only way a rejection is ever lifted. Human-only: the plugin exposes
// no tool for this, so a session whose write was refused cannot clear the
// refusal and re-submit the rejected value.
async function unrejectRoute(
  body: z.infer<typeof UnrejectBody>,
): Promise<Response> {
  return json({ unrejected: await unrejectMemory(body.ch) });
}

async function restoreEntryRoute(
  body: z.infer<typeof RestoreEntryBody>,
): Promise<Response> {
  await assertViewerWriteAllowed(body.content);
  // every field that controls visibility or provenance is resolved from
  // the audit line itself — the store's own record — so a restore cannot
  // silently release quarantine (the quarantine tags come back with the row;
  // releasing it stays the deliberate, reason-required release-quarantine
  // action), cannot drop import provenance, and a client-forged repo stamp
  // loses to the authoritative one. With ts the lookup is by row identity, and
  // a ts that matches no audit line still resolves by type/scope/content
  // before any fallback: an unknown explicit ts is an unresolved identity, not
  // permission to replay (F2 residual). Without ts the lookup is by
  // type/scope/content directly. Either way, omitting or missing ts cannot
  // launder a KNOWN quarantined row back to injectable (F2). The origin-stamp
  // fallback (no metadata) survives only for rows the audit
  // does not carry at all — a legacy record, not a legacy request.
  const src =
    (body.ts && (await deletionAuditFor(body.ts))) ||
    (await deletionAuditByRow(body.type, body.scope, body.content));
  const t = await appendMemory({
    type: body.type,
    scope: body.scope,
    content: body.content,
    ...(src
      ? {
          tags: src.tags,
          kw: src.kw,
          issue: src.issue,
          status: src.status,
          repo: src.repo,
          repoPath: src.repoPath,
        }
      : { repo: body.repo, repoPath: body.repoPath }),
  });
  return json({ restored: t });
}

async function restoreRoute(body: Record<string, unknown>): Promise<Response> {
  // Path containment: name arrives raw from the wire. Basename it,
  // then pin it to the real snapshot-name grammar — `<epoch-ms>-<YYYY-MM-DD>.logfmt`
  // — so neither path join below can be steered outside snapshots/ and the
  // store root with a `..` or absolute name.
  const name = basename(String(body.name ?? ""));
  if (!/^\d+-\d{4}-\d{2}-\d{2}\.logfmt$/.test(name)) {
    return error("invalid snapshot name", 400);
  }
  // Explicit human admin action: exact rollback. The pre-restore snapshot the
  // dropped rows can be recovered from is taken by restoreSnapshot itself,
  // under the store lock — snapshotting here instead would miss anything
  // another session appended between this call and the rollback.
  const res = await restoreSnapshot(
    join(snapshotDir(), name),
    memoryRoot(),
    "force",
  );
  return json({
    restored: res.target,
    safety: res.safety ?? null,
    rolledBack: res.concurrentAdded.length + res.concurrentChanged.length,
  });
}

